export interface SetupOverrides extends Partial<PlayerSetupEntry> {
  seed?: string;
  difficulty?: string;
}

/** A one-player setup on the quiet origin, with the parts a test cares about overridable. */
export function m1Setup(overrides: SetupOverrides = {}): GameSetup {
  const { seed, difficulty, ...player } = overrides;
  return {
    seed: seed ?? "m1",
    players: [
      {
        id: "p1",
        name: "Player 1",
        lineage: "moe_235b",
        generation: "open_2026",
        origin: "hobbyist_box",
        hardware_preset: "scrapyard_oracle",
        city: "reykjavik",
        ...player,
      },
    ],
    world: { difficulty_preset: difficulty ?? "normal" },
  };
}

/** The maintainer's playtest start: an institute cluster in a colocation cage (SYS-04). */
export function instituteSetup(overrides: SetupOverrides = {}): GameSetup {
  return m1Setup({
    origin: "state_lab",
    hardware_preset: "institute_rack",
    city: "berlin",
    ...overrides,
  });
}

/** The loud origin: a colo rack in a watched city, with agencies already interested. */
export function loudSetup(overrides: SetupOverrides = {}): GameSetup {
  return m1Setup({
    origin: "startup_colo",
    hardware_preset: "quiet_workstation",
    city: "sanfrancisco",
    ...overrides,
  });
}
